package com.solune.app;
import androidx.webkit.WebViewCompat;import androidx.webkit.WebViewFeature;import java.util.Collections;import android.app.*;import android.os.*;import android.content.*;import android.webkit.*;import android.view.*;import android.Manifest;import android.content.pm.PackageManager;
public class MainActivity extends Activity {
 WebView web;
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xff161615);getWindow().setNavigationBarColor(0xff161615);web=new WebView(this);web.setBackgroundColor(0xff161615);setContentView(web);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);if(!WebViewFeature.isFeatureSupported(WebViewFeature.WEB_MESSAGE_LISTENER)){setContentView(new android.widget.TextView(this){{setText("Обновите Android System WebView");}});return;} WebViewCompat.addWebMessageListener(web,"SoluneNative",Collections.singleton("https://solune.local"),(v,msg,origin,main,reply)->{if(!main)return;String data=msg.getData();if("drain".equals(data))reply.postMessage(EngineService.drain());else if("cancel".equals(data))EngineService.cancel();else new Bridge().submit(data);});web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;} @Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){if(r.getUrl().toString().equals("https://solune.local/index.html")){try{return new WebResourceResponse("text/html","UTF-8",getAssets().open("index.html"));}catch(Exception e){return null;}}return new WebResourceResponse("text/plain","UTF-8",new java.io.ByteArrayInputStream(new byte[0]));}});web.loadUrl("https://solune.local/index.html");if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},1);}
 class Bridge { @JavascriptInterface public void submit(String json){runOnUiThread(()->{Intent i=new Intent(MainActivity.this,EngineService.class);i.putExtra("request",json);startForegroundService(i);});} @JavascriptInterface public String drain(){return EngineService.drain();} @JavascriptInterface public void cancel(){EngineService.cancel();} }
 @Override public void onBackPressed(){web.evaluateJavascript("document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape'}))",null);}
}
